func total(_ data: [Int], parts: Int) async -> Int {
    await withTaskGroup(of: Int.self) { group in          // master
        for i in 0..<parts {
            group.addTask { sumPart(data, i) }            // identical workers
        }
        var total = 0
        for await partial in group { total += partial }   // join + combine
        return total
    }
}
